# Table traversal: walk schema (tables -> columns -> foreign keys), BFS from a table.
schema = {'orders': {'columns': ['id', 'customer_id->customers.id']}, 'customers': {'columns': ['id', 'name']}, 'items': {'columns': ['id', 'order_id->orders.id']}}
def neighbors(table):
    out = set()
    for col in schema.get(table, {}).get("columns", []):
        if "->" in col:
            out.add(col.split("->")[1].rsplit(".", 1)[0])
    for t, spec in schema.items():
        for col in spec.get("columns", []):
            if col.endswith("->" + table + ".id") or ("->" in col and col.split("->")[1].startswith(table + ".")):
                out.add(t)
    return sorted(out)
start = "orders"
seen, queue, order = {start}, [start], []
while queue:
    t = queue.pop(0); order.append(t)
    for nb in neighbors(t):
        if nb not in seen: seen.add(nb); queue.append(nb)
print("Reachable from", start, ":", order)
for t in order:
    print(f"  {t}: {', '.join(schema[t]['columns'])}")

